<script setup lang="ts">import {ref,onMounted,computed} from 'vue';import {plansStore} from '../stores/plans';import {reportsStore} from '../stores/reports';import {approve} from '../api/plans';import {create} from '../api/reports';import {downloadReport} from '../api/client';import {isAdmin,canEdit} from '../stores/auth';import {useTask} from '../hooks/useTask';import PageTitle from '../components/common/PageTitle.vue';import Notice from '../components/common/Notice.vue';import StatusBadge from '../components/common/StatusBadge.vue';import PipeTable from '../components/common/PipeTable.vue';const {items,error,reload}=plansStore(),reports=reportsStore(),selected=ref<any>(null),note=ref('已复核道路施工与运维排班，允许交接执行。');const task=useTask();const sorted=computed(()=>[...items.value].sort((a,b)=>(b.work_date||'').localeCompare(a.work_date||'')||b.created_at?.localeCompare(a.created_at||'')));const planReports=computed(()=>reports.items.value);async function load(){await Promise.all([reload(),reports.reload()]);selected.value=items.value.find(x=>x.id===selected.value?.id)||sorted.value[0]}onMounted(load);function review(){task.execute(async()=>{await approve(selected.value.id,note.value);await load();task.message.value='巡检计划已审批通过。'})}function report(){task.execute(async()=>{const r=await create({name:selected.value.name+' · 正式交接',plan_id:selected.value.id});await reports.reload();await downloadReport(r.id);task.message.value='正式报告已生成并开始下载。'})}</script><template><PageTitle eyebrow="05 / FIELD HANDOVER" title="把推演，交给现场。" description="分析师按作业日期与班组生成清单，系统避开同日已占用管段；负责人审批后导出，每次交接都有明确依据与复核记录。"/><Notice :error="error||task.error.value" :message="task.message.value"/><div class="plan-selector"><button v-for="p in sorted" :key="p.id" @click="selected=p" :class="{active:selected?.id===p.id}"><span>{{p.name}}</span><small class="mono">{{p.work_date||'未标日期'}} · {{p.crew||'未分班'}}</small><small v-if="p.shortfall" class="shortfall-flag">缺额 {{p.shortfall}} 段</small><StatusBadge :status="p.status"/></button></div><section v-if="selected" class="section-block"><div class="section-heading"><div><h2>{{selected.name}}</h2><small class="mono">{{selected.run_id}} / {{selected.pipes.length}} 段</small><div class="plan-meta"><span>作业日期 <b>{{selected.work_date||'—'}}</b></span><span>班组 <b>{{selected.crew||'—'}}</b></span><span>预算 <b>{{selected.budget}} 段</b></span><span>实际清单 <b>{{selected.pipes.length}} 段</b></span></div></div><StatusBadge :status="selected.status"/></div><Notice v-if="selected.shortfall" :error="`可用管段不足：预算 ${selected.budget} 段，仅能安排 ${selected.pipes.length} 段，缺额 ${selected.shortfall} 段。请调整作业日期、预算或等待占用释放。`"/><Notice v-if="selected.occupied_pipe_ids?.length" :message="`已按风险排序跳过同日已批准占用的 ${selected.occupied_pipe_ids.length} 段管段：${selected.occupied_pipe_ids.slice(0,6).join('、')}${selected.occupied_pipe_ids.length>6?' 等':''}`"/><div v-if="selected.conflicts?.length" class="notice error" role="alert"><b>审批冲突：</b>以下 {{selected.conflicts.length}} 段在 {{selected.work_date}} 已被其他班组的已批准计划占用，本份计划整份保留待审，请调整清单或日期后重新提交。<ul class="conflict-list"><li v-for="c in selected.conflicts" :key="c.pipe_id" class="mono">{{c.pipe_id}} ← {{c.crew}} / {{c.plan_name}}</li></ul></div><PipeTable :pipes="selected.pipes"/><div class="review-panel"><div><div class="eyebrow">RESPONSIBILITY / REVIEW</div><h2>{{selected.status==='approved'?'已完成负责人复核':'等待负责人复核'}}</h2><p>{{selected.review_note||'请检查道路施工约束、班组工时与现场安全条件，再批准交接。'}}</p><small v-if="selected.approved_by">审批人：{{selected.approved_by}}<template v-if="selected.approved_at"> · {{new Date(selected.approved_at).toLocaleString('zh-CN')}}</template></small></div><div class="review-actions"><template v-if="selected.status==='draft'"><textarea v-if="isAdmin" v-model="note" aria-label="审批意见"/><button class="primary" v-if="isAdmin" @click="review" :disabled="task.busy.value">批准交接 →</button><p v-else>此计划需要管理员审批。</p></template><button v-if="selected.status==='approved'&&canEdit" class="primary" @click="report" :disabled="task.busy.value">生成并下载 CSV →</button><button v-for="r in planReports.filter(x=>x.plan_id===selected.id)" :key="r.id" @click="task.execute(()=>downloadReport(r.id))">下载已归档报告 ↗</button></div></div></section><div v-else class="empty">尚无巡检计划。请从评估解释页选择作业日期与班组，生成一份预算内清单。</div></template>
